package client

import (
	"fmt"
	"time"

	"github.com/cloudwego/kitex/pkg/endpoint"
	"github.com/cloudwego/kitex/pkg/utils"
	internal_client "github.com/cloudwego/kitex/internal/client"
)

// WithUnaryOptions applies multiple unary-specific options
func WithUnaryOptions(opts ...UnaryOption) Option {
	return Option{F: func(o *internal_client.Options, di *utils.Slice) {
		di.Push("WithUnaryOptions")
		for _, opt := range opts {
			opt.F(o, di)
		}
	}}
}

// WithUnaryRPCTimeout sets the RPC timeout for unary calls
func WithUnaryRPCTimeout(d time.Duration) UnaryOption {
	return UnaryOption{F: func(o *internal_client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryRPCTimeout(%s)", d))
		o.UnaryOptions.RPCTimeout = &d
		o.Configs.RPCTimeout() // Also set in global config for backward compatibility
	}}
}

// WithUnaryMiddleware adds middleware for unary RPCs
func WithUnaryMiddleware(mw endpoint.Middleware) UnaryOption {
	return UnaryOption{F: func(o *internal_client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryMiddleware(%+v)", utils.GetFuncName(mw)))
		o.UnaryOptions.Middlewares = append(o.UnaryOptions.Middlewares, mw)
	}}
}

// WithUnaryMiddlewareBuilder adds middleware builder for unary RPCs
func WithUnaryMiddlewareBuilder(mwb endpoint.MiddlewareBuilder) UnaryOption {
	return UnaryOption{F: func(o *internal_client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryMiddlewareBuilder(%+v)", utils.GetFuncName(mwb)))
		o.UnaryOptions.MiddlewareBuilders = append(o.UnaryOptions.MiddlewareBuilders, mwb)
		o.MWBs = append(o.MWBs, mwb) // Also add to global for backward compatibility
	}}
}

func (fr *Framer) readAndCheckFrameHeader() (http2.FrameHeader, error) {
	buf, err := fr.reader.Next(frameHeaderLen)
	if err != nil {
		return http2.FrameHeader{}, err
	}

	fh := http2.FrameHeader{
		Length:   uint32(buf[0])<<16 | uint32(buf[1])<<8 | uint32(buf[2]),
		Type:     http2.FrameType(buf[3]),
		Flags:    http2.Flags(buf[4]),
		StreamID: binary.BigEndian.Uint32(buf[5:]) & (1<<31 - 1),
		// valid:    true,
	}

	// Check if frame length exceeds max read size
	if fh.Length > fr.maxReadSize {
		return http2.FrameHeader{}, fmt.Errorf("%s or invalid frame (first4Bytes=%#x, second4Bytes=%#x)", 
			http2.ErrFrameTooLarge, buf[:4], buf[4:8])
	}

	return fh, nil
}

