// Package transport provides predefined transport protocol.
package transport

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0

	TTHeader Protocol = 1 << iota // 2
	Framed                        // 4
	HTTP                          // 8
	GRPC                          // 16
	HESSIAN2                      // 32
	TTHeaderStreaming             // 64 - dedicated flag, not a composite
	GRPCStreaming                 // 128

	// Composite protocols
	TTHeaderFramed = TTHeader | Framed // 6
)

// DefaultProtocol is the default transport protocol.
const DefaultProtocol = Framed

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	// Check for exact matches first (including common composites)
	switch tp {
	case PurePayload:
		return "PurePayload"
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	}

	// Handle composite protocols by building name with | operator
	var parts []string
	if tp&TTHeader != 0 {
		parts = append(parts, "TTHeader")
	}
	if tp&Framed != 0 {
		parts = append(parts, "Framed")
	}
	if tp&HTTP != 0 {
		parts = append(parts, "HTTP")
	}
	if tp&GRPC != 0 {
		parts = append(parts, "GRPC")
	}
	if tp&HESSIAN2 != 0 {
		parts = append(parts, "HESSIAN2")
	}
	if tp&TTHeaderStreaming != 0 {
		parts = append(parts, "TTHeaderStreaming")
	}
	if tp&GRPCStreaming != 0 {
		parts = append(parts, "GRPCStreaming")
	}

	if len(parts) > 0 {
		result := parts[0]
		for i := 1; i < len(parts); i++ {
			result += "|" + parts[i]
		}
		return result
	}

	return Unknown
}

func (p *connPool) Dump() map[string]interface{} {
	result := make(map[string]interface{})
	result["pool_size"] = p.size
	result["remote_service"] = p.remoteService
	result["short_conn_mode"] = p.connOpts.ShortConn

	connections := make(map[string]interface{})
	p.conns.Range(func(key, value interface{}) bool {
		addr := key.(string)
		trans := value.(*transports)

		connInfo := make(map[string]interface{})
		connInfo["capacity"] = trans.size
		connInfo["round_robin_index"] = atomic.LoadUint32(&trans.index)

		// Collect per-connection status
		connStatus := make([]map[string]interface{}, 0, trans.size)
		activeCount := 0
		for i := 0; i < int(trans.size); i++ {
			status := make(map[string]interface{})
			status["slot"] = i

			if trans.cliTransports[i] == nil {
				status["state"] = "empty"
			} else {
				if trans.cliTransports[i].(grpc.IsActive).IsActive() {
					status["state"] = "active"
					activeCount++
				} else {
					status["state"] = "inactive"
				}
			}
			connStatus = append(connStatus, status)
		}

		connInfo["active_connections"] = activeCount
		connInfo["connections"] = connStatus
		connections[addr] = connInfo
		return true
	})

	result["addresses"] = connections
	result["total_addresses"] = len(connections)
	return result
}

